import{_ as a,o as t,c as d,a2 as i}from"./chunks/framework.DHmNT4rz.js";const u=JSON.parse('{"title":"@saasweave/cache","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/packages/cache.md","filePath":"reference/packages/cache.md","lastUpdated":null}'),s={name:"reference/packages/cache.md"};function c(o,e,r,l,n,h){return t(),d("div",null,[...e[0]||(e[0]=[i('<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/packages/cache/README.md" target="_blank" rel="noreferrer"><code>packages/cache/README.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="saasweave-cache" tabindex="-1">@saasweave/cache <a class="header-anchor" href="#saasweave-cache" aria-label="Permalink to &quot;@saasweave/cache&quot;">​</a></h1><p>Redis-backed cache and rate limiting with explicit failure policies for security-sensitive state.</p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Examples</th><th>Redis down in production</th></tr></thead><tbody><tr><td>Availability caches</td><td>Dashboard reads, AI usage summaries</td><td>Bounded per-process memory fallback</td></tr><tr><td>Security state</td><td>Auth/export/log rate limits, API keys, IP allowlists</td><td><code>failureMode: failClosed</code> when configured</td></tr></tbody></table><p>Use <code>resolveSecurityFailureMode()</code> for auth rate limits, export limits, API-key lookups, and IP allowlist caches. Security paths must not silently fall back to per-process memory across replicas when <code>REDIS_URL</code> is configured.</p><table tabindex="0"><thead><tr><th>Condition</th><th>Availability cache</th><th>Security cache / rate limits</th></tr></thead><tbody><tr><td><code>REDIS_URL</code> set and Redis healthy</td><td>Shared Redis with tag invalidation</td><td>Distributed across replicas</td></tr><tr><td><code>REDIS_URL</code> set and Redis unavailable</td><td>Bounded memory fallback</td><td>Fail closed (reject / cache miss to DB)</td></tr><tr><td><code>REDIS_URL</code> unset</td><td>Bounded memory fallback</td><td>Fail open (single-process only)</td></tr></tbody></table><p><code>checkRedisReady()</code> reports unhealthy when <code>REDIS_URL</code> is configured and unreachable, which makes <code>/health/ready</code> fail in production.</p><p>In <strong>production</strong>, env validation requires <code>REDIS_URL</code> unless <code>ALLOW_SINGLE_INSTANCE_FALLBACK=true</code> is set (single-instance escape hatch).</p><h2 id="key-exports" tabindex="-1">Key exports <a class="header-anchor" href="#key-exports" aria-label="Permalink to &quot;Key exports&quot;">​</a></h2><ul><li><code>@saasweave/cache</code> — cache helpers (<code>cacheGet</code>, <code>cacheSet</code>, <code>cacheWrap</code>, tag invalidation, <code>failureMode</code>)</li><li><code>@saasweave/cache/rate-limit</code> — fixed-window rate limiter with <code>failureMode</code></li><li><code>@saasweave/cache/redis</code> — connection helpers and readiness checks</li><li><code>resolveSecurityFailureMode()</code> — shared fail-closed policy helper</li></ul><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><p>Validated in <code>@saasweave/env</code> (<code>ENV_SERVER</code>):</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>REDIS_URL</code></td><td>unset</td><td>Required in production unless <code>ALLOW_SINGLE_INSTANCE_FALLBACK=true</code></td></tr><tr><td><code>ALLOW_SINGLE_INSTANCE_FALLBACK</code></td><td><code>false</code></td><td>Single-instance production escape hatch</td></tr><tr><td><code>CACHE_PREFIX</code></td><td><code>saasweave</code></td><td>Redis key namespace prefix</td></tr><tr><td><code>CACHE_DEFAULT_TTL_SECONDS</code></td><td><code>300</code></td><td>Default TTL for cache entries</td></tr></tbody></table><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @saasweave/cache</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:unit</span></span></code></pre></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/SaaSWeave/reference/packages/jobs">packages/jobs</a> — shares Redis connection for BullMQ</li><li><a href="/SaaSWeave/reference/packages/env">packages/env</a> — production Redis and mail validation</li></ul>',18)])])}const b=a(s,[["render",c]]);export{u as __pageData,b as default};
